//  >>> TEMA <<<
//  Troque as cores aqui. Aceita com ou sem "#" (ex.: "#c4a65e" ou "c4a65e").
//  Também dá para sobrescrever pela página, ANTES de carregar este arquivo:
//    <script>window.PLAYER_THEME = { "theme-color": "#c4a65e", "center-play": "#000000" };</script>

var PLAYER_THEME_DEFAULT = {
  "theme-color":    "#ff0000", // cor principal: botão central, barra de progresso, bolinha, hover dos menus
  "center-play":    "#fefefe", // triângulo de play dentro do botão central
  "icons":          "#ffffff", // ícones da barra de controles (play, volume, tela cheia, config, compartilhar...)
  "background":     "#000000", // fundo da tela do player
  "toolbar":        "#000000", // fundo (degradê) da barra de controles
  "progress-bg":    "#ffffff", // trilho da barra de progresso (fica translúcido)
  "progress-load":  "#ffffff", // parte já carregada da barra de progresso
  "progress-hover": "#ffffff", // prévia ao passar o mouse na barra de progresso
  "volume":         "#ffffff", // barra de volume (preenchida)
  "volume-bg":      "#ffffff", // trilho da barra de volume
  "volume-hover":   "#ffffff", // barra de volume ao passar o mouse
  "menu-bg":        "#000000", // fundo dos menus (configurações e playlist)
  "menu-text":      "#ffffff"  // texto dos menus
};

var PLAYER_THEME = (function (base, custom) {
  var t = {};
  for (var k in base) t[k] = base[k];
  for (var k2 in (custom || {})) t[k2] = custom[k2];
  return t;
})(PLAYER_THEME_DEFAULT, window.PLAYER_THEME);

function playerThemeColor(name) { return String(PLAYER_THEME[name]).replace("#", ""); }

//  >>> CONFIGURAÇÃO DO PLAYER (botões, posições, comportamento) <<<
//  on: 1 = botão ligado, on: 0 = desligado.

