    function TimeSub(srt) {
      var tmp = srt.split(':');
      var out = 0;
      tmp.length == 2 ? tmp.unshift("00") : '';
      tmp[0] != '00' ? out += tmp[0] * 3600 : '';
      tmp[1] != '00' ? out += tmp[1] * 60 : '';
      out += tmp[2].substr(0, 2) * 1;
      out = out * 10 + tmp[2].substr(3, 1) * 1;
      return out
    };

